import * as THREE from './three.module.mjs';
import {panoramaPoint} from './real-courses.mjs';
export function buildPanoramaWorld({world,track,addCollider}){
 const owned=new Set(),group=new THREE.Group();group.name='Mount Panorama terrain and circuit facilities';world.add(group);
 const mat=(color,extra={})=>{const m=new THREE.MeshStandardMaterial({color,roughness:.92,...extra});owned.add(m);return m};
 const grass=mat(0xffffff,{vertexColors:true}),earth=mat(0x78634b),white=mat(0xe6e2d5),roof=mat(0x465354),glass=mat(0x496675),trunk=mat(0x817665),leaf=mat(0x667950);
 const add=(geometry,material,x,y,z,parent=group)=>{owned.add(geometry);const m=new THREE.Mesh(geometry,material);m.position.set(x,y,z);m.receiveShadow=true;parent.add(m);return m};
 const box=(w,h,d,m,x,y,z,parent=group)=>add(new THREE.BoxGeometry(w,h,d),m,x,y,z,parent);
 const [width,depth]=track.course.mapSize,nx=Math.ceil(width/1.5),nz=Math.ceil(depth/1.5),g=new THREE.PlaneGeometry(width,depth,nx,nz);g.rotateX(-Math.PI/2);const positions=g.attributes.position,colors=[],green=new THREE.Color(),low=new THREE.Color(0xa2a373),high=new THREE.Color(0x64734b);
 for(let i=0;i<positions.count;i++){const x=positions.getX(i),z=positions.getZ(i),h=track.terrainHeight(x,z);positions.setY(i,h);const patch=.07*Math.sin(x*.083+z*.04)*Math.sin(z*.075);green.copy(low).lerp(high,Math.max(0,Math.min(1,h/34+patch)));colors.push(green.r,green.g,green.b)}
 g.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));g.computeVertexNormals();const terrain=add(g,grass,0,0,0);terrain.name='Continuous mountain surface — road, infield and outer slopes';terrain.castShadow=true;
 // Exposed board edges show the relief continuing through the whole diorama.
 const rim=[],rimIndices=[];const outline=[];for(let i=0;i<=nx;i++)outline.push([-width/2+width*i/nx,-depth/2]);for(let i=1;i<=nz;i++)outline.push([width/2,-depth/2+depth*i/nz]);for(let i=1;i<=nx;i++)outline.push([width/2-width*i/nx,depth/2]);for(let i=1;i<nz;i++)outline.push([-width/2,depth/2-depth*i/nz]);
 outline.forEach(([x,z],i)=>{rim.push(x,track.terrainHeight(x,z),z,x,-5,z);const j=(i+1)%outline.length;rimIndices.push(i*2,j*2,i*2+1,j*2,j*2+1,i*2+1)});const rg=new THREE.BufferGeometry();rg.setAttribute('position',new THREE.Float32BufferAttribute(rim,3));rg.setIndex(rimIndices);rg.computeVertexNormals();add(rg,mat(0x806b50,{side:THREE.DoubleSide}),0,0,0);box(width,.8,depth,earth,0,-5.4,0);
 let seed=54328;const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};const treePoints=[];
 for(let i=0;i<1200&&treePoints.length<340;i++){const x=(random()-.5)*(width-15),z=(random()-.5)*(depth-15),h=track.terrainHeight(x,z),d=track.terrainDistance(x,z);if(d<8||z>147||random()>(z<0?.9:.35))continue;treePoints.push({x,z,h,size:2.3+random()*2.5})}
 const tg=new THREE.CylinderGeometry(.22,.35,1,6),lg=new THREE.IcosahedronGeometry(1,1);owned.add(tg);owned.add(lg);const trunks=new THREE.InstancedMesh(tg,trunk,treePoints.length),leaves=new THREE.InstancedMesh(lg,leaf,treePoints.length),dummy=new THREE.Object3D();
 treePoints.forEach((p,i)=>{addCollider(p.x,p.z,.4,p.h);dummy.position.set(p.x,p.h+p.size*.7,p.z);dummy.scale.set(1,p.size*1.4,1);dummy.updateMatrix();trunks.setMatrixAt(i,dummy.matrix);dummy.position.y=p.h+p.size*1.65;dummy.scale.set(p.size*.85,p.size*.8,p.size*.74);dummy.rotation.y=i*2.1;dummy.updateMatrix();leaves.setMatrixAt(i,dummy.matrix);leaves.setColorAt(i,new THREE.Color().setHSL(.22+random()*.045,.17+random()*.15,.28+random()*.1))});trunks.castShadow=true;leaves.castShadow=true;group.add(trunks,leaves);
 const pit=panoramaPoint(127,534),pitGroup=new THREE.Group();pitGroup.name='Main Straight pit building';pitGroup.position.set(pit.x,track.terrainHeight(pit.x,pit.z),pit.z);pitGroup.rotation.y=Math.atan2(32,6);group.add(pitGroup);for(let d=-15;d<=15;d+=3)addCollider(pit.x+Math.sin(pitGroup.rotation.y)*d,pit.z+Math.cos(pitGroup.rotation.y)*d,2,pitGroup.position.y+1);box(4,2.5,34,white,0,1.25,0,pitGroup);box(4.8,.35,35,roof,0,2.7,0,pitGroup);for(let i=-4;i<=4;i++){box(.05,1.7,2.4,glass,-2.03,1.2,i*3.5,pitGroup);box(2,.45,2.4,white,0,3.1,i*3.5,pitGroup)}
 function label(text,x,z,width=15){const y=track.terrainHeight(x,z),cv=document.createElement('canvas');cv.width=768;cv.height=100;const ctx=cv.getContext('2d');ctx.fillStyle='#20372b';ctx.fillRect(0,0,768,100);ctx.fillStyle='#eef5d8';ctx.font='bold 44px Arial';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(text,384,52,730);const texture=new THREE.CanvasTexture(cv);texture.colorSpace=THREE.SRGBColorSpace;owned.add(texture);const m=new THREE.SpriteMaterial({map:texture,depthTest:true,transparent:true});owned.add(m);const sprite=new THREE.Sprite(m);sprite.position.set(x,y+5,z);sprite.scale.set(width,width/7.68,1);group.add(sprite);return sprite}
 for(const [name,px,pz,w]of [['MOUNT PANORAMA',285,152,30],['MOUNTAIN STRAIGHT',258,407,21],['THE CUTTING',374,285,16],['SKYLINE',295,73,14],['THE DIPPER',235,42,14],["FORREST’S ELBOW",144,13,20],['CONROD STRAIGHT',102,222,22],['THE CHASE',48,397,15]]){const p=panoramaPoint(px,pz);label(name,p.x,p.z,w)}
 const start=track.nodes[0],startGroup=new THREE.Group();startGroup.name='Main Straight start and finish gantry';startGroup.position.set(start.x,start.y,start.z);startGroup.rotation.y=start.heading;group.add(startGroup);for(const side of[-1,1])box(.3,4.3,.3,roof,side*(track.course.width/2+1),2.15,0,startGroup);box(track.course.width+2.7,.85,.4,white,0,4.35,0,startGroup);
 label('START / FINISH',start.x,start.z,12);
 return{dispose(){for(const r of owned)r.dispose();group.removeFromParent()}};
}
